{
  "rules": [
    {
      "conditions": [
        {"attr": "has_security_keyword", "op": "eq", "value": true}
      ],
      "action": "SECURITY_INCIDENT",
      "note": "Cualquier ticket con palabras clave de seguridad se dirige al equipo de incidentes de seguridad."
    },
    {
      "conditions": [
        {"attr": "severity", "op": "eq", "value": 1}
      ],
      "action": "ONCALL_ESCALATION",
      "note": "Incidencias de severidad crítica (1) se escalan a guardia inmediatamente."
    },
    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "enterprise"},
        {"attr": "severity", "op": "lte", "value": 2}
      ],
      "action": "ACCOUNT_MANAGER",
      "note": "Clientes enterprise con severidad alta o crítica se asignan al gestor de cuenta."
    },
    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "enterprise"}
      ],
      "action": "T2_TECHNICAL",
      "note": "Clientes enterprise que no hayan sido capturados por reglas anteriores van a soporte técnico."
    },
    {
      "conditions": [
        {"attr": "product", "op": "eq", "value": "billing"}
      ],
      "action": "BILLING_SPECIALIST",
      "note": "Tickets sobre facturación van al especialista de billing."
    },
    {
      "conditions": [
        {"attr": "severity", "op": "lte", "value": 2},
        {"attr": "product", "op": "in", "value": ["api", "integrations"]}
      ],
      "action": "T3_ENGINEERING",
      "note": "Incidencias de severidad alta o crítica en API o integraciones se derivan a ingeniería."
    },
    {
      "conditions": [
        {"attr": "severity", "op": "lte", "value": 2}
      ],
      "action": "T2_TECHNICAL",
      "note": "Incidencias de severidad alta o crítica (no cubiertas antes) van a soporte técnico."
    },
    {
      "conditions": [
        {"attr": "channel", "op": "eq", "value": "chat"},
        {"attr": "off_hours", "op": "eq", "value": true}
      ],
      "action": "SELF_SERVICE_DEFLECT",
      "note": "Tickets por chat fuera de horario se desvían a autoservicio."
    },
    {
      "conditions": [
        {"attr": "prior_tickets_30d", "op": "gte", "value": 10}
      ],
      "action": "ACCOUNT_MANAGER",
      "note": "Clientes con muchos tickets recientes (10 o más) se asignan al gestor de cuenta para retención."
    },
    {
      "conditions": [
        {"attr": "language", "op": "in", "value": ["es", "pt", "de", "fr"]}
      ],
      "action": "T1_GENERAL",
      "note": "Tickets en idiomas distintos al inglés van a primer nivel para traducción y clasificación."
    },
    {
      "conditions": [
        {"attr": "product", "op": "eq", "value": "mobile"}
      ],
      "action": "T2_TECHNICAL",
      "note": "Tickets sobre la app móvil van a soporte técnico."
    },
    {
      "conditions": [
        {"attr": "severity", "op": "eq", "value": 4}
      ],
      "action": "SELF_SERVICE_DEFLECT",
      "note": "Incidencias de severidad baja (4) se responden con autoservicio."
    },
    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "free"}
      ],
      "action": "SELF_SERVICE_DEFLECT",
      "note": "Usuarios gratuitos van a autoservicio por defecto."
    },
    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "pro"}
      ],
      "action": "T1_GENERAL",
      "note": "Usuarios pro van a primer nivel de soporte."
    },
    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "business"}
      ],
      "action": "T2_TECHNICAL",
      "note": "Usuarios business van a soporte técnico."
    },
    {
      "conditions": [
        {"attr": "product", "op": "eq", "value": "dashboard"}
      ],
      "action": "T1_GENERAL",
      "note": "Tickets sobre el dashboard van a primer nivel."
    },
    {
      "conditions": [
        {"attr": "channel", "op": "eq", "value": "phone"}
      ],
      "action": "T2_TECHNICAL",
      "note": "Llamadas telefónicas se dirigen a soporte técnico."
    },
    {
      "conditions": [
        {"attr": "channel", "op": "eq", "value": "email"}
      ],
      "action": "T1_GENERAL",
      "note": "Tickets por email van a primer nivel."
    },
    {
      "conditions": [
        {"attr": "channel", "op": "eq", "value": "portal"}
      ],
      "action": "SELF_SERVICE_DEFLECT",
      "note": "Tickets enviados desde el portal se responden con autoservicio."
    }
  ],
  "note": "La base de reglas prioriza seguridad y criticidad, luego segmenta por tier y producto, con reglas de desvío a autoservicio para casos de baja prioridad o fuera de horario. Las reglas más específicas (con más condiciones) se colocan antes para que el motor las aplique correctamente en el nivel 1."
}

