      "action": "BILLING_SPECIALIST",
      "note": "Facturacion urgente (severidad 1-2) -> especialista facturacion"
    },
    {
      "conditions": [
        {"attr": "product", "op": "eq", "value": "billing"},
        {"attr": "prior_tickets_30d", "op": "gte", "value": 3}
      ],
      "action": "BILLING_SPECIALIST",
      "note": "Facturacion con varios tickets este mes -> especialista facturacion"
    },
    {
      "conditions": [
        {"attr": "product", "op": "eq", "value": "billing"}
      ],
      "action": "SELF_SERVICE_DEFLECT",
