      "action": "ACCOUNT_MANAGER",
      "note": "Business con muchisimos tickets -> gestor de cuenta"
    },
    {
      "conditions": [
        {"attr": "product", "op": "in", "value": ["api", "integrations"]},
        {"attr": "severity", "op": "lte", "value": 2}
