      "action": "SELF_SERVICE_DEFLECT",
      "note": "Llamadas de free -> autoservicio"
    },
    {
      "conditions": [
        {"attr": "channel", "op": "eq", "value": "phone"},
        {"attr": "off_hours", "op": "eq", "value": true},
        {"attr": "customer_tier", "op": "neq", "value": "enterprise"}
