      "action": "T1_GENERAL",
      "note": "Telefono fuera de horario (no enterprise) -> primer nivel"
    },
    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "free"},
        {"attr": "severity", "op": "gte", "value": 3}
      ],
      "action": "SELF_SERVICE_DEFLECT",
      "note": "Free no urgente -> autoservicio"
    },
    {
      "conditions": [
        {"attr": "severity", "op": "eq", "value": 4},
        {"attr": "prior_tickets_30d", "op": "eq", "value": 0}
      ],
      "action": "SELF_SERVICE_DEFLECT",
      "note": "Severidad minima sin tickets previos -> autoservicio"
