    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "free"}
      ],
      "action": "SELF_SERVICE_DEFLECT",
      "note": "Free por defecto -> autoservicio"
    },
    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "pro"}
      ],
      "action": "T1_GENERAL",
      "note": "Pro por defecto -> primer nivel"
    },
    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "business"}
      ],
      "action": "T1_GENERAL",
      "note": "Business por defecto -> primer nivel"
    },
    {
      "conditions": [
        {"attr": "customer_tier", "op": "eq", "value": "enterprise"}
